//! Differential ratchet for `src/engine/battleScriptSemiInvulnerableOpcode.ts`.
//! Expected complete projected results, Halt reasons, and the exact gated
//! role error are generated by invoking the canonical TypeScript opcode
//! handlers; regenerate with `node --experimental-strip-types
//! core-rs/tools/gen-battle-script-semi-invulnerable-vectors.mjs`.

use factory_core::battle_script_semi_invulnerable::{
    apply_battle_script_clearsemiinvulnerablebit, apply_battle_script_clearstatusfromeffect,
    apply_battle_script_setsemiinvulnerablebit, register_battle_script_clearsemiinvulnerablebit,
    register_battle_script_clearstatusfromeffect, register_battle_script_setsemiinvulnerablebit,
    BattleScriptClearstatusfromeffectExecution, BattleScriptClearstatusfromeffectInstruction,
    BattleScriptClearstatusfromeffectOutcome, BattleScriptSemiInvulnerableBattlerState,
    BattleScriptSemiInvulnerableBitInstruction, BattleScriptSemiInvulnerableRoles,
    BattleScriptSemiInvulnerableRules,
};
use factory_core::battle_script_semi_invulnerable_vectors_gen::{
    BattleScriptSemiInvulnerableVectorCase, BattleScriptSemiInvulnerableVectorState,
    BATTLE_SCRIPT_SEMI_INVULNERABLE_BRANCH_CENSUS, BATTLE_SCRIPT_SEMI_INVULNERABLE_CASES,
    BATTLE_SCRIPT_SEMI_INVULNERABLE_CATEGORY_CENSUS, BATTLE_SCRIPT_SEMI_INVULNERABLE_OPCODE_CENSUS,
    BATTLE_SCRIPT_SEMI_INVULNERABLE_REGISTRATION_CASES,
    BATTLE_SCRIPT_SEMI_INVULNERABLE_REGISTRATION_OUTCOME_CENSUS,
    BATTLE_SCRIPT_SEMI_INVULNERABLE_VECTOR_CORPUS_SHA256,
};

fn rules(value: BattleScriptSemiInvulnerableVectorState) -> BattleScriptSemiInvulnerableRules {
    BattleScriptSemiInvulnerableRules {
        battlers: std::array::from_fn(|index| BattleScriptSemiInvulnerableBattlerState {
            status1: value.status1[index],
            status2: value.status2[index],
            status3: value.status3[index],
        }),
        move_effect_byte: value.move_effect_byte,
        current_move: value.current_move,
        selector_roles: BattleScriptSemiInvulnerableRoles { attacker: value.attacker },
    }
}

fn vector_state(
    value: BattleScriptSemiInvulnerableRules,
) -> BattleScriptSemiInvulnerableVectorState {
    BattleScriptSemiInvulnerableVectorState {
        status1: value.battlers.map(|b| b.status1),
        status2: value.battlers.map(|b| b.status2),
        status3: value.battlers.map(|b| b.status3),
        move_effect_byte: value.move_effect_byte,
        current_move: value.current_move,
        attacker: value.selector_roles.attacker,
    }
}

#[test]
fn complete_projected_outputs_halts_and_gated_error_match_canonical_typescript() {
    assert_eq!(BATTLE_SCRIPT_SEMI_INVULNERABLE_CASES.len(), 33);
    for (index, case) in BATTLE_SCRIPT_SEMI_INVULNERABLE_CASES.iter().enumerate() {
        execute_case(index, case);
    }
}

fn execute_case(index: usize, case: &BattleScriptSemiInvulnerableVectorCase) {
    let input = rules(case.initial);
    match case.opcode {
        "clearstatusfromeffect" => {
            let execution = BattleScriptClearstatusfromeffectExecution {
                program_counter: case.program_counter,
                opcode_id: 0x18,
                operand_expression: case.operand_expression,
                battler: case.initial.attacker,
            };
            let outcome = apply_battle_script_clearstatusfromeffect(&execution, &input);
            assert_eq!(
                input,
                rules(case.initial),
                "case {index} {}: mutated input",
                case.label
            );
            match (outcome, case.branch) {
                (
                    BattleScriptClearstatusfromeffectOutcome::Advance { rules: actual },
                    "advance",
                ) => {
                    let expected = case.expected.unwrap_or_else(|| {
                        panic!("case {index} {}: missing expected state", case.label)
                    });
                    assert_eq!(
                        vector_state(actual),
                        expected,
                        "case {index} {}: output",
                        case.label
                    );
                }
                (BattleScriptClearstatusfromeffectOutcome::Halt(halt), "halt") => {
                    let expected = case.halt.as_ref().unwrap_or_else(|| {
                        panic!("case {index} {}: missing expected halt", case.label)
                    });
                    assert_eq!(halt.program_counter, expected.program_counter);
                    assert_eq!(halt.opcode_id, expected.opcode_id);
                    assert_eq!(halt.opcode_name, expected.opcode_name);
                    assert_eq!(halt.source_construct, expected.source_construct);
                    assert_eq!(halt.source_file, expected.source_file);
                    assert_eq!(halt.source_line, expected.source_line);
                }
                (outcome, branch) => panic!(
                    "case {index} {}: outcome {outcome:?} disagrees with expected branch {branch}",
                    case.label
                ),
            }
        }
        "setsemiinvulnerablebit" | "clearsemiinvulnerablebit" => {
            let apply = if case.opcode == "setsemiinvulnerablebit" {
                apply_battle_script_setsemiinvulnerablebit
            } else {
                apply_battle_script_clearsemiinvulnerablebit
            };
            let result = apply(&input);
            assert_eq!(
                input,
                rules(case.initial),
                "case {index} {}: mutated input",
                case.label
            );
            match (result, case.branch) {
                (Ok(actual), "advance") => {
                    let expected = case.expected.unwrap_or_else(|| {
                        panic!("case {index} {}: missing expected state", case.label)
                    });
                    assert_eq!(
                        vector_state(actual),
                        expected,
                        "case {index} {}: output",
                        case.label
                    );
                }
                (Err(error), "missing-attacker-role") => {
                    assert_eq!(
                        error.to_string(),
                        case.expected_error.unwrap_or_else(|| panic!(
                            "case {index} {}: missing expected error",
                            case.label
                        )),
                        "case {index} {}: exact error",
                        case.label,
                    );
                }
                (result, branch) => panic!(
                    "case {index} {}: result {result:?} disagrees with expected branch {branch}",
                    case.label
                ),
            }
        }
        other => panic!("case {index} {}: unknown opcode {other}", case.label),
    }
}

#[test]
fn registration_cases_match_canonical_typescript() {
    assert_eq!(BATTLE_SCRIPT_SEMI_INVULNERABLE_REGISTRATION_CASES.len(), 16);
    let good_effect = BattleScriptClearstatusfromeffectInstruction {
        opcode_name: "B_SCR_OP_CLEARSTATUSFROMEFFECT",
        program_counter: 10,
        opcode_id: 0x18,
        dispatcher: "Cmd_clearstatusfromeffect",
        operand_width_bytes: Some(1),
        operand_expression: Some("BS_ATTACKER"),
    };
    let good_set = BattleScriptSemiInvulnerableBitInstruction {
        opcode_name: "B_SCR_OP_SETSEMIINVULNERABLEBIT",
        program_counter: 20,
        opcode_id: 0xc5,
        dispatcher: "Cmd_setsemiinvulnerablebit",
        operand_count: 0,
    };
    let good_clear = BattleScriptSemiInvulnerableBitInstruction {
        opcode_name: "B_SCR_OP_CLEARSEMIINVULNERABLEBIT",
        program_counter: 30,
        opcode_id: 0xc6,
        dispatcher: "Cmd_clearsemiinvulnerablebit",
        operand_count: 0,
    };

    for case in &BATTLE_SCRIPT_SEMI_INVULNERABLE_REGISTRATION_CASES {
        match case.label {
            "clearstatus_success" => {
                let starts = vec![good_effect; 5];
                assert_eq!(
                    register_battle_script_clearstatusfromeffect(&starts).unwrap(),
                    case.opcode_id.unwrap()
                );
            }
            "clearstatus_wrong_count" => {
                let starts = vec![good_effect; 4];
                assert_eq!(
                    register_battle_script_clearstatusfromeffect(&starts)
                        .unwrap_err()
                        .to_string(),
                    case.expected_error.unwrap()
                );
            }
            "clearstatus_wrong_dispatcher" => {
                let mut starts = vec![good_effect; 5];
                starts[0].dispatcher = "Cmd_setminimize";
                assert_eq!(
                    register_battle_script_clearstatusfromeffect(&starts)
                        .unwrap_err()
                        .to_string(),
                    case.expected_error.unwrap()
                );
            }
            "clearstatus_wrong_operand_count" => {
                let mut starts = vec![good_effect; 5];
                starts[0].operand_width_bytes = None;
                starts[0].operand_expression = None;
                assert_eq!(
                    register_battle_script_clearstatusfromeffect(&starts)
                        .unwrap_err()
                        .to_string(),
                    case.expected_error.unwrap()
                );
            }
            "clearstatus_wrong_operand_width" => {
                let mut starts = vec![good_effect; 5];
                starts[0].operand_width_bytes = Some(4);
                assert_eq!(
                    register_battle_script_clearstatusfromeffect(&starts)
                        .unwrap_err()
                        .to_string(),
                    case.expected_error.unwrap()
                );
            }
            "clearstatus_wrong_expression" => {
                let mut starts = vec![good_effect; 5];
                starts[0].operand_expression = Some("BS_TARGET");
                assert_eq!(
                    register_battle_script_clearstatusfromeffect(&starts)
                        .unwrap_err()
                        .to_string(),
                    case.expected_error.unwrap()
                );
            }
            "setbit_success" => {
                assert_eq!(
                    register_battle_script_setsemiinvulnerablebit(&[good_set]).unwrap(),
                    case.opcode_id.unwrap()
                );
            }
            "setbit_wrong_count_zero" => {
                assert_eq!(
                    register_battle_script_setsemiinvulnerablebit(&[])
                        .unwrap_err()
                        .to_string(),
                    case.expected_error.unwrap()
                );
            }
            "setbit_wrong_count_two" => {
                assert_eq!(
                    register_battle_script_setsemiinvulnerablebit(&[good_set, good_set])
                        .unwrap_err()
                        .to_string(),
                    case.expected_error.unwrap()
                );
            }
            "setbit_wrong_dispatcher" => {
                let mut bad = good_set;
                bad.dispatcher = "Cmd_setminimize";
                assert_eq!(
                    register_battle_script_setsemiinvulnerablebit(&[bad])
                        .unwrap_err()
                        .to_string(),
                    case.expected_error.unwrap()
                );
            }
            "setbit_wrong_operand_count" => {
                let mut bad = good_set;
                bad.operand_count = 1;
                assert_eq!(
                    register_battle_script_setsemiinvulnerablebit(&[bad])
                        .unwrap_err()
                        .to_string(),
                    case.expected_error.unwrap()
                );
            }
            "clearbit_success" => {
                let starts = vec![good_clear; 2];
                assert_eq!(
                    register_battle_script_clearsemiinvulnerablebit(&starts).unwrap(),
                    case.opcode_id.unwrap()
                );
            }
            "clearbit_wrong_count_one" => {
                assert_eq!(
                    register_battle_script_clearsemiinvulnerablebit(&[good_clear])
                        .unwrap_err()
                        .to_string(),
                    case.expected_error.unwrap()
                );
            }
            "clearbit_wrong_count_three" => {
                let starts = vec![good_clear; 3];
                assert_eq!(
                    register_battle_script_clearsemiinvulnerablebit(&starts)
                        .unwrap_err()
                        .to_string(),
                    case.expected_error.unwrap()
                );
            }
            "clearbit_wrong_dispatcher" => {
                let mut starts = vec![good_clear; 2];
                starts[0].dispatcher = "Cmd_setminimize";
                assert_eq!(
                    register_battle_script_clearsemiinvulnerablebit(&starts)
                        .unwrap_err()
                        .to_string(),
                    case.expected_error.unwrap()
                );
            }
            "clearbit_wrong_operand_count" => {
                let mut starts = vec![good_clear; 2];
                starts[0].operand_count = 1;
                assert_eq!(
                    register_battle_script_clearsemiinvulnerablebit(&starts)
                        .unwrap_err()
                        .to_string(),
                    case.expected_error.unwrap()
                );
            }
            other => panic!("unhandled registration case label {other}"),
        }
    }
}

#[test]
fn domain_category_opcode_branch_censuses_and_corpus_hash_are_ratchet_pinned() {
    assert_eq!(
        BATTLE_SCRIPT_SEMI_INVULNERABLE_CATEGORY_CENSUS,
        [
            ("clearsemiinvulnerablebit-idempotence", 1),
            ("clearsemiinvulnerablebit-missing-attacker-role", 1),
            ("clearsemiinvulnerablebit-move-matrix", 5),
            ("clearstatusfromeffect-byte-zero-edge", 1),
            ("clearstatusfromeffect-call-sites", 5),
            ("clearstatusfromeffect-charging-matrix", 8),
            ("clearstatusfromeffect-missing-operand", 1),
            ("clearstatusfromeffect-primary-branch", 1),
            ("clearstatusfromeffect-rage", 1),
            ("clearstatusfromeffect-selector-unavailable", 1),
            ("clearstatusfromeffect-untouched-sibling", 1),
            ("setsemiinvulnerablebit-idempotence", 1),
            ("setsemiinvulnerablebit-missing-attacker-role", 1),
            ("setsemiinvulnerablebit-move-matrix", 5),
        ],
    );
    assert_eq!(
        BATTLE_SCRIPT_SEMI_INVULNERABLE_OPCODE_CENSUS,
        [
            ("clearsemiinvulnerablebit", 7),
            ("clearstatusfromeffect", 19),
            ("setsemiinvulnerablebit", 7),
        ],
    );
    assert_eq!(
        BATTLE_SCRIPT_SEMI_INVULNERABLE_BRANCH_CENSUS,
        [("advance", 29), ("halt", 2), ("missing-attacker-role", 2)],
    );
    assert_eq!(
        BATTLE_SCRIPT_SEMI_INVULNERABLE_REGISTRATION_OUTCOME_CENSUS,
        [("err", 13), ("ok", 3)],
    );
    assert_eq!(
        BATTLE_SCRIPT_SEMI_INVULNERABLE_VECTOR_CORPUS_SHA256,
        "b8ba30d39c8ce71b25d3af147f8f55adcee07aa90362877dcf66ffefd9a7dc03",
    );
}
